#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
int main(){HWND h=FindWindowW(L"ZimClipWindow",0);DWORD tid=GetWindowThreadProcessId(h,0);HMODULE m=LoadLibraryW(L"scroll-reentry.dll");HHOOK hook=SetWindowsHookExW(WH_CALLWNDPROC,(HOOKPROC)GetProcAddress(m,"Reentry"),m,tid);if(!hook)return 5;int n=0;DWORD_PTR out=0;HWND v=GetDlgItem(h,74),c=GetDlgItem(v,45);for(int cycle=0;cycle<10;cycle++){for(int layout=0;layout<4;layout++){if(!SendMessageTimeoutW(c,CB_SETCURSEL,layout,0,SMTO_ABORTIFHUNG,2000,&out))goto fail;if(!SendMessageTimeoutW(v,WM_COMMAND,MAKEWPARAM(45,CBN_SELCHANGE),(LPARAM)c,SMTO_ABORTIFHUNG,2000,&out))goto fail;for(int step=0;step<8;step++){if(!SendMessageTimeoutW(v,WM_MOUSEWHEEL,MAKEWPARAM(0,step%2?-120:120),0,SMTO_ABORTIFHUNG,2000,&out))goto fail;n++;}if(!SendMessageTimeoutW(v,WM_VSCROLL,SB_BOTTOM,0,SMTO_ABORTIFHUNG,2000,&out))goto fail;if(!SendMessageTimeoutW(v,WM_VSCROLL,SB_TOP,0,SMTO_ABORTIFHUNG,2000,&out))goto fail;}}printf("PASS layout_transitions=40 wheel_events=%d forced_bar_paint_per_child_move=on\n",n);UnhookWindowsHookEx(hook);return 0;fail:printf("FAIL wheel_count=%d err=%lu\n",n,GetLastError());UnhookWindowsHookEx(hook);return 3;}
